create extension if not exists vector with schema extensions;
create extension if not exists pgcrypto with schema extensions;

create type public.species as enum ('dog','cat','horse','cattle','buffalo','goat','sheep','other_livestock');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, display_name text, locale text not null default 'en' check(locale in ('en','ur')), created_at timestamptz not null default now());
create table public.user_roles(user_id uuid primary key references auth.users(id) on delete cascade, role text not null check(role in ('user','veterinarian','admin')) default 'user');
create table public.animals(id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, name text not null, species public.species not null, breed text, date_of_birth date, estimated_age text, sex text, reproductive_status text, weight numeric check(weight>0), weight_unit text default 'kg', color_description text, microchip_identifier text, diet text, pregnancy_status text, regular_veterinarian text, notes text, profile_image_path text, created_at timestamptz default now(), updated_at timestamptz default now());
create index animals_owner_idx on public.animals(owner_id);
create table public.animal_allergies(id uuid primary key default gen_random_uuid(), animal_id uuid not null references public.animals(id) on delete cascade, owner_id uuid not null references auth.users(id) on delete cascade, allergen text not null, notes text, created_at timestamptz default now());
create table public.animal_conditions(id uuid primary key default gen_random_uuid(), animal_id uuid not null references public.animals(id) on delete cascade, owner_id uuid not null references auth.users(id) on delete cascade, name text not null, status text, diagnosed_at date, notes text);
create table public.animal_weights(id uuid primary key default gen_random_uuid(), animal_id uuid not null references public.animals(id) on delete cascade, owner_id uuid not null references auth.users(id) on delete cascade, measured_at timestamptz not null, weight numeric not null check(weight>0), unit text not null);
create table public.medical_records(id uuid primary key default gen_random_uuid(), animal_id uuid not null references public.animals(id) on delete cascade, owner_id uuid not null references auth.users(id) on delete cascade, record_type text not null, title text not null, occurred_at timestamptz not null, details jsonb not null default '{}', notes text, created_at timestamptz default now());
create table public.vaccinations(id uuid primary key default gen_random_uuid(), animal_id uuid not null references public.animals(id) on delete cascade, owner_id uuid not null references auth.users(id) on delete cascade, vaccine_name text not null, administered_at date not null, next_due_at date, dose_number text, batch_lot text, veterinarian_clinic text, attachment_path text, notes text);
create table public.medications(id uuid primary key default gen_random_uuid(), animal_id uuid not null references public.animals(id) on delete cascade, owner_id uuid not null references auth.users(id) on delete cascade, name text not null, form text, concentration text, prescribed_instructions text not null, start_date date, end_date date, prescribing_veterinarian text, purpose text, notes text, active boolean not null default true);
create table public.uploaded_files(id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, animal_id uuid references public.animals(id) on delete cascade, bucket text not null, storage_path text not null, original_filename text not null, mime_type text not null, size_bytes bigint not null check(size_bytes>=0), checksum text, created_at timestamptz default now());
create table public.lab_reports(id uuid primary key default gen_random_uuid(), animal_id uuid not null references public.animals(id) on delete cascade, owner_id uuid not null references auth.users(id) on delete cascade, file_id uuid references public.uploaded_files(id), report_date date, laboratory text, extraction_status text not null default 'pending', extracted_text text, created_at timestamptz default now());
create table public.lab_results(id uuid primary key default gen_random_uuid(), report_id uuid not null references public.lab_reports(id) on delete cascade, test_name text not null, result_value text, unit text, reference_range text, report_flag text, raw_line text);
create table public.conversations(id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, animal_id uuid references public.animals(id) on delete set null, title text not null default 'New conversation', mode text not null check(mode in ('owner','veterinarian')), language text not null check(language in ('en','ur')), created_at timestamptz default now(), updated_at timestamptz default now());
create table public.messages(id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.conversations(id) on delete cascade, owner_id uuid not null references auth.users(id) on delete cascade, role text not null check(role in ('user','assistant','system')), content text not null, urgency text, created_at timestamptz default now());
create table public.knowledge_documents(id uuid primary key default gen_random_uuid(), title text not null, filename text not null, checksum text not null unique, source_organization text, source_url text, publication_date date, document_version text, species text, topic text, language text, source_type text, status text not null default 'pending', is_trusted boolean not null default false, embedding_model text, error text, uploaded_by uuid references auth.users(id), created_at timestamptz default now());
create table public.knowledge_chunks(id uuid primary key default gen_random_uuid(), document_id uuid not null references public.knowledge_documents(id) on delete cascade, chunk_number int not null, content text not null, page_number int, section_heading text, embedding extensions.vector(1024), embedding_model text not null, metadata jsonb not null default '{}', search_vector tsvector generated always as (to_tsvector('simple',content)) stored, unique(document_id,chunk_number));
create index knowledge_chunks_hnsw on public.knowledge_chunks using hnsw(embedding vector_cosine_ops);
create index knowledge_chunks_fts on public.knowledge_chunks using gin(search_vector);
create table public.document_ingestion_jobs(id uuid primary key default gen_random_uuid(), document_id uuid not null references public.knowledge_documents(id) on delete cascade, status text not null, stage text, processed_chunks int default 0, error text, started_at timestamptz, completed_at timestamptz, created_at timestamptz default now());
create table public.message_citations(id uuid primary key default gen_random_uuid(), message_id uuid not null references public.messages(id) on delete cascade, chunk_id uuid not null references public.knowledge_chunks(id), ordinal int not null, excerpt text not null, unique(message_id,ordinal));
create table public.feedback(id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, message_id uuid not null references public.messages(id) on delete cascade, rating smallint not null check(rating in (-1,1)), comment text, created_at timestamptz default now());
create table public.rag_evaluation_runs(id uuid primary key default gen_random_uuid(), started_by uuid references auth.users(id), configuration jsonb not null, status text not null, metrics jsonb, created_at timestamptz default now(), completed_at timestamptz);
create table public.rag_evaluations(id uuid primary key default gen_random_uuid(), run_id uuid not null references public.rag_evaluation_runs(id) on delete cascade, question text not null, expected_answer text, relevant_document_ids uuid[], result jsonb not null);
create table public.audit_logs(id bigint generated always as identity primary key, actor_id uuid references auth.users(id), action text not null, entity_type text not null, entity_id text, metadata jsonb not null default '{}', created_at timestamptz default now());

alter table public.profiles enable row level security; alter table public.user_roles enable row level security; alter table public.animals enable row level security; alter table public.animal_allergies enable row level security; alter table public.animal_conditions enable row level security; alter table public.animal_weights enable row level security; alter table public.medical_records enable row level security; alter table public.vaccinations enable row level security; alter table public.medications enable row level security; alter table public.uploaded_files enable row level security; alter table public.lab_reports enable row level security; alter table public.lab_results enable row level security; alter table public.conversations enable row level security; alter table public.messages enable row level security; alter table public.feedback enable row level security; alter table public.knowledge_documents enable row level security; alter table public.knowledge_chunks enable row level security; alter table public.document_ingestion_jobs enable row level security; alter table public.message_citations enable row level security; alter table public.rag_evaluation_runs enable row level security; alter table public.rag_evaluations enable row level security; alter table public.audit_logs enable row level security;

create policy profiles_own on public.profiles for all to authenticated using((select auth.uid())=id) with check((select auth.uid())=id);
create policy roles_read_own on public.user_roles for select to authenticated using((select auth.uid())=user_id);
create policy animals_own on public.animals for all to authenticated using((select auth.uid())=owner_id) with check((select auth.uid())=owner_id);
create policy allergies_own on public.animal_allergies for all to authenticated using((select auth.uid())=owner_id) with check((select auth.uid())=owner_id);
create policy conditions_own on public.animal_conditions for all to authenticated using((select auth.uid())=owner_id) with check((select auth.uid())=owner_id);
create policy weights_own on public.animal_weights for all to authenticated using((select auth.uid())=owner_id) with check((select auth.uid())=owner_id);
create policy records_own on public.medical_records for all to authenticated using((select auth.uid())=owner_id) with check((select auth.uid())=owner_id);
create policy vaccinations_own on public.vaccinations for all to authenticated using((select auth.uid())=owner_id) with check((select auth.uid())=owner_id);
create policy medications_own on public.medications for all to authenticated using((select auth.uid())=owner_id) with check((select auth.uid())=owner_id);
create policy files_own on public.uploaded_files for all to authenticated using((select auth.uid())=owner_id) with check((select auth.uid())=owner_id);
create policy reports_own on public.lab_reports for all to authenticated using((select auth.uid())=owner_id) with check((select auth.uid())=owner_id);
create policy results_via_report on public.lab_results for select to authenticated using(exists(select 1 from public.lab_reports r where r.id=report_id and r.owner_id=(select auth.uid())));
create policy conversations_own on public.conversations for all to authenticated using((select auth.uid())=owner_id) with check((select auth.uid())=owner_id);
create policy messages_own on public.messages for all to authenticated using((select auth.uid())=owner_id) with check((select auth.uid())=owner_id);
create policy feedback_own on public.feedback for all to authenticated using((select auth.uid())=owner_id) with check((select auth.uid())=owner_id);

insert into storage.buckets(id,name,public) values ('animal-images','animal-images',false),('medical-records','medical-records',false),('lab-reports','lab-reports',false),('knowledge-documents','knowledge-documents',false) on conflict(id) do nothing;
create policy storage_owner_read on storage.objects for select to authenticated using(bucket_id in ('animal-images','medical-records','lab-reports') and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy storage_owner_insert on storage.objects for insert to authenticated with check(bucket_id in ('animal-images','medical-records','lab-reports') and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy storage_owner_update on storage.objects for update to authenticated using((storage.foldername(name))[1]=(select auth.uid())::text) with check((storage.foldername(name))[1]=(select auth.uid())::text);
create policy storage_owner_delete on storage.objects for delete to authenticated using((storage.foldername(name))[1]=(select auth.uid())::text);
